import { createContext, useContext } from "react";
import { useCurrentFrame } from "remotion";
import raw from "../data/timeline.json";

/** Generated by `python tools/build.py` from storyboard.json + analysis/beats.json. Never edit by hand. */
export type Ev = { f: number; fs: number[]; ticks: number[] };
export type Cam = { x: number; y: number; z: number };
export type Trans = {
  type: string; // cut flash fade black pan push zoom whip wipe iris blur rise glitch
  f0: number; // absolute frames of the transition window
  f1: number;
  dir: number; // +1 / -1 (push / whip / wipe / rise)
  axis: "x" | "y";
  at: [number, number]; // origin for zoom / iris, screen px
  bow: number; // pan: how much to pull back mid-move (0..1)
};
export type SceneData = {
  id: string;
  type: string;
  from: number;
  dur: number;
  props: Record<string, any>;
  events: Record<string, Ev>;
  subs: { in: number; out: number }[];
  fadeIn: number;
  fadeOut: number;
  cam0: Cam;
  cam1: Cam;
  in: Trans | null;
};
export type Timeline = {
  fps: number;
  width: number;
  height: number;
  frames: number;
  duration: number;
  meta: Record<string, any>;
  glyphs: string;
  bgm: { bpm: number; key: string; source?: string };
  beats: number[];
  downbeats: number[];
  hits: Record<string, number>;
  scenes: SceneData[];
  subs: { zh: string; en: string; from: number; to: number }[];
  flashes: { f: number; n: number }[];
  shakes: { f: number; amp: number; n: number }[];
  cues: { f: number; name: string }[];
};

export const TL = raw as unknown as Timeline;
export const FPS = TL.fps;

/** off = frames between the scene's mount (start of its transition window) and its nominal start. */
export const SceneCtx = createContext<{ s: SceneData; off: number } | null>(null);
/** The global camera at the current frame (world → screen). Identity when no scene sets "cam". */
export const CamCtx = createContext<Cam>({ x: 0, y: 0, z: 1 });
export const useCamera = () => useContext(CamCtx);
/** Inverse of the scene's camera transform; <Hud> (and <Meta>) use it to stay put on screen. */
export const HudCtx = createContext<string>("none");

/** Inside a scene: local frame/time (0 = the scene's nominal start; negative while its in-transition plays)
 * plus its beat-snapped events (all frames relative to the scene start). */
export const useScene = () => {
  const c = useContext(SceneCtx);
  if (!c) throw new Error("useScene() must be used inside a scene");
  const s = c.s;
  const f = useCurrentFrame() - c.off;
  const ev = (name: string): Ev => {
    const e = s.events[name];
    if (!e) throw new Error(`scene "${s.id}" has no event "${name}" — add it to storyboard.json and re-run tools/build.py`);
    return e;
  };
  /** Frame of an event, or `fallback` (seconds from scene start) when the storyboard doesn't define it. */
  const at = (name: string, fallback?: number): number =>
    s.events[name] ? s.events[name].f : fallback !== undefined ? Math.round(fallback * FPS) : ev(name).f;
  return {
    scene: s,
    props: s.props,
    f,
    t: f / FPS,
    dur: s.dur,
    ev,
    at,
    has: (name: string) => name in s.events,
    /** seconds since an event frame (negative before it) */
    since: (frame: number) => (f - frame) / FPS,
    sub: (i: number) => s.subs[i],
    cam: s.cam0,
  };
};
